// The env templates `pnpm configure:env` writes. This file is the source of
// truth for deploy/.env.production.example: edit the template here and run
// the tool, never the generated file.

/** A run of `# ` comment lines followed by `KEY=value` lines. */
interface Section {
  readonly comment: readonly string[];
  readonly entries: readonly (readonly [key: string, value: string])[];
}

const PRODUCTION_HEADER: readonly string[] = [
  'Production settings for the homelab LXC (docs/deploy/homelab.md). Copy it',
  'to .env at the repo root on the host and keep it there only:',
  '',
  '  cp deploy/.env.production.example .env && chmod 600 .env',
  '',
  'Generated by `pnpm configure:env`: edit the template in',
  'packages/configure-env/src/template.ts, not this file, which the tool',
  'rewrites.',
  '',
  'Nothing here is secret (the contact details end up in the public bundle),',
  "but .env is the host's own copy: scripts/deploy.sh rewrites IMAGE_TAG in",
  'it and it is never committed.',
];

const PRODUCTION_SECTIONS: readonly Section[] = [
  {
    comment: [
      'Every plain `docker compose` command run from the repo root uses the base',
      'file plus the production override, under a stable project name (container',
      'names stay the same across deploys).',
    ],
    entries: [
      ['COMPOSE_FILE', 'docker-compose.yml:deploy/compose.prod.yml'],
      ['COMPOSE_PROJECT_NAME', 'elvisgastelum-com'],
    ],
  },
  {
    comment: [
      "The running release: scripts/deploy.sh sets it to the deployed commit's",
      'short hash and rolls back to the previous value when a deploy fails. Set',
      "it to the checkout's short hash before the first start",
      '(`git rev-parse --short HEAD`); `latest` names no commit, so a failing',
      'deploy after it cannot roll back automatically.',
    ],
    entries: [['IMAGE_TAG', 'latest']],
  },
  {
    comment: [
      "Where the site is published: the LXC's own LAN address, so Caddy on",
      'raspberrypi3b reaches it (the firewall allows only CADDY_ADDRESS).',
      'Replace <CT ID> with the container ID, which is also the last octet of',
      'its address.',
    ],
    entries: [
      ['WEB_HOST', '192.168.1.<CT ID>'],
      ['WEB_PORT', '8080'],
    ],
  },
  {
    comment: [
      'Contact details, embedded in the bundle at build time (README, "Contact',
      'variables"). Empty keeps the defaults in apps/web/src/config/site.ts',
      '(elvisgastelum@proton.me and WhatsApp 526381177267). The WhatsApp number',
      'is digits only, country code first; `off` hides the WhatsApp link.',
    ],
    entries: [
      ['VITE_CONTACT_EMAIL', ''],
      ['VITE_CONTACT_WHATSAPP', ''],
    ],
  },
  {
    comment: [
      'The address Caddy (raspberrypi3b) connects to this LXC from: its LAN',
      'address, or its Tailnet address if the Caddy upstream is a Tailnet name.',
      'Only the firewall rule in docs/deploy/homelab.md uses it; the static site',
      'reads no forwarded headers.',
    ],
    entries: [['CADDY_ADDRESS', '192.168.1.70']],
  },
];

const commentLines = (lines: readonly string[]) =>
  lines.map((line) => (line ? `# ${line}` : '#'));

const renderSection = ({ comment, entries }: Section) =>
  [
    ...commentLines(comment),
    ...entries.map(([key, value]) => `${key}=${value}`),
  ].join('\n');

/** The whole deploy/.env.production.example, ending in a newline. */
export function renderProductionExample(): string {
  const blocks = [
    commentLines(PRODUCTION_HEADER).join('\n'),
    ...PRODUCTION_SECTIONS.map(renderSection),
  ];
  return `${blocks.join('\n\n')}\n`;
}

// --- .env.example ---------------------------------------------------------

/** The keys .env.example must have, in order (those docker-compose.yml reads). */
export const EXAMPLE_KEYS = [
  'WEB_HOST',
  'WEB_PORT',
  'VITE_CONTACT_EMAIL',
  'VITE_CONTACT_WHATSAPP',
] as const;

export type ExampleKey = (typeof EXAMPLE_KEYS)[number];
export type EnvValues = Record<ExampleKey, string>;

/** docker-compose.yml's defaults. */
export const DEFAULT_VALUES: Readonly<EnvValues> = {
  WEB_HOST: '127.0.0.1',
  WEB_PORT: '8080',
  VITE_CONTACT_EMAIL: '',
  VITE_CONTACT_WHATSAPP: '',
};

const KEY_COMMENTS: Partial<Record<ExampleKey, string>> = {
  WEB_HOST:
    '# Address the web container is published on; keep 127.0.0.1 behind a reverse proxy on the same host.',
  WEB_PORT: '# Host port the site is published on.',
};

/** The contact keys share one comment, written once before the first of them. */
const CONTACT_COMMENT = [
  '# Contact details embedded in the bundle at build time (README, "Contact variables").',
  '# Empty keeps the defaults in apps/web/src/config/site.ts; VITE_CONTACT_WHATSAPP=off hides WhatsApp.',
];

const isContactKey = (key: ExampleKey) => key.startsWith('VITE_CONTACT_');

/**
 * The comment and `KEY=value` lines for the given keys, groups separated by
 * a blank line, ending in a newline. Empty for no keys.
 */
export function renderExampleBlock(
  keys: readonly ExampleKey[],
  values: Readonly<EnvValues> = DEFAULT_VALUES,
): string {
  const lines: string[] = [];
  let contactDone = false;
  keys.forEach((key, index) => {
    if (isContactKey(key)) {
      if (!contactDone) {
        if (index > 0) lines.push('');
        lines.push(...CONTACT_COMMENT);
        contactDone = true;
      }
    } else {
      if (index > 0) lines.push('');
      const comment = KEY_COMMENTS[key];
      if (comment) lines.push(comment);
    }
    lines.push(`${key}=${values[key]}`);
  });
  return lines.length ? `${lines.join('\n')}\n` : '';
}
